headers={'/m/a.safetensors':{'x':{'data_offsets':[0,8]}},'/m/b.safetensors':{'y':{'data_offsets':[0,12]}}}
m={'x':'/m/a.safetensors','y':'/m/b.safetensors'}
out={'metadata':{'total_size':sum(headers[v][k]['data_offsets'][1]-headers[v][k]['data_offsets'][0] for k,v in m.items())},'weight_map':{k:os.path.basename(v) for k,v in m.items()}}
assert out['metadata']['total_size']==20
print(json.dumps(out))
old='multi_modal_projector.mm_input_projection_weight'; new='multi_modal_projector.mm_input_projection.weight'
raw={old:{'data_offsets':[0,8]}}
normalized={new:raw[old]}
print(json.dumps({'raw_key':old,'exported_key':next(iter(normalized)),'exported_key_exists_in_raw_header':new in raw}))

